import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlToasterComponent } from '@domg-wc/components/block';

// VlToasterComponent registreert ook vl-alert.
registerWebComponents([VlToasterComponent, VlButtonComponent]);

document.querySelector('#default-toaster-button').addEventListener('click', () => {
    const toaster = document.querySelector('#default-toaster');
    const template = document.querySelector('template#alert-success-template');

    // kloon de melding uit de template en voeg ze toe aan het default slot van de toaster
    const alert = template.content.cloneNode(true).querySelector('#alert-success');
    toaster.appendChild(alert);
});

