import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlToasterComponent } from '@domg-wc/components/block';

registerWebComponents([VlToasterComponent, VlButtonComponent]);

document.querySelector('#button-technical-error').addEventListener('vl-click', () => {
    const toaster = document.querySelector('#toaster-show-alert');
    // showAlert() maakt een vl-alert en zet elke key met een waarde als attribuut.
    toaster.showAlert({
        title: 'Technische storing',
        icon: 'warning',
        type: 'warning',
        message: 'Door een technische storing is dit loket tijdelijk niet beschikbaar.',
        closable: true,
    });
});

components-block-toaster--toaster-fade-o.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlLoaderComponent, VlToasterComponent } from '@domg-wc/components/block';

registerWebComponents([VlToasterComponent, VlButtonComponent, VlLoaderComponent]);

const toaster = document.querySelector('vl-toaster#toaster-fade-out');

// show() met de selector van een template toont een kloon van het eerste element erin. Met fade-out verdwijnt die
// melding vanzelf: de animatie start na 4,4 s en duurt 0,3 s, daarna verwijdert de toaster ze.
document.querySelector('#button-error').addEventListener('vl-click', () => toaster.show('#alert-error-template'));
document.querySelector('#button-loader').addEventListener('vl-click', () => toaster.show('#alert-loader-template'));
